"""`docs/supported.md` is generated by `tools/gen_supported.py`: the committed file must be what
the script writes, so the page cannot drift from the tables the integration uses."""

from __future__ import annotations

import importlib.util
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def _generator():
    spec = importlib.util.spec_from_file_location("gen_supported", ROOT / "tools" / "gen_supported.py")
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_supported_page_is_what_the_script_writes() -> None:
    generated = _generator().render()
    committed = (ROOT / "docs" / "supported.md").read_text(encoding="utf-8")
    assert committed == generated, "docs/supported.md is stale: run `python tools/gen_supported.py`"


def test_every_listed_integration_has_a_display_name() -> None:
    gen = _generator()
    domains = {platform for row in gen.sd.METER_ROWS for platform in row.platforms}
    domains |= {platform for row in gen.sd.BATTERY_ROWS for platform in row.platforms}
    domains |= {str(case["domain"]) for case in gen.vehicle_cases() if case["soc"] not in (None, "ambiguous")}
    domains |= set(gen.pool_detect.POOL_DOMAINS) | set(gen.pool_detect.PANEL_DOMAINS) | set(gen.spa_detect.SPA_DOMAINS)
    domains |= set(gen.sauna_detect.SAUNA_DOMAINS)
    missing = sorted(domain for domain in domains if domain not in gen.NAMES)
    assert not missing, f"add a display name to NAMES in tools/gen_supported.py: {missing}"


def test_page_has_one_section_per_category() -> None:
    text = _generator().render()
    for heading in (
        "# Supported EV chargers, meters, batteries, heat pumps and cars",
        "## Supported EV chargers",
        "## Supported grid meters",
        "## Supported house batteries",
        "## Supported heat pumps",
        "## Supported pool heat pumps, spas and saunas",
        "## Supported vehicles",
        "## Supported solar forecast",
    ):
        assert f"\n{heading}\n" in f"\n{text}", heading


def test_the_phase_switching_note_names_exactly_the_platforms_that_can_switch() -> None:
    import custom_components.spotnav.execution.chargers  # noqa: F401 - registers every platform's paths
    from custom_components.spotnav.execution import charger_profiles as cp
    from custom_components.spotnav.execution.chargers import registry

    noted = {profile.platform for profile in cp._PROFILES if profile.phase_switching}
    assert noted == set(registry._PHASE_SWITCH)
    peblar = next(profile for profile in cp._PROFILES if profile.platform == "peblar")
    assert "Phase switching for solar through the Force single phase switch; needs the smart charging strategy Default." in (
        _generator().charger_notes(peblar)
    )


def test_the_overview_names_every_battery_spotnav_reads_and_works_out_what_it_does_with_each() -> None:
    gen = _generator()
    keys = {key for entry in gen.OVERVIEW for key in entry.keys}
    adapters = {entry.adapter for entry in gen.OVERVIEW if entry.adapter}

    # Every battery row and every adapter is some maker's in the overview, so the overview cannot fall behind.
    missing = sorted(key for row in gen.sd.BATTERY_ROWS for key in gen.row_keys(row) if key not in keys)
    assert not missing, f"add the integration to OVERVIEW in tools/gen_supported.py: {missing}"
    # `victron_modbus` is read with Victron's row; `solaredge_modbus` (core and binsentsu's integration, facts only) with SolarEdge's;
    # `growatt_modbus` (0xAHA's integration) with Growatt's, beside the `solax_modbus` plugin.
    assert {adapter.brand for adapter in gen.ba.ADAPTERS} - {"victron_modbus", "solaredge_modbus", "growatt_modbus"} <= adapters

    rows = {entry.brand: gen._overview_row(entry) for entry in gen.OVERVIEW}
    assert rows["Sigenergy"][2].startswith("Yes: ") and rows["Sigenergy"][3] == gen.CONTROL_OPT_IN
    assert rows["Huawei (SUN2000, LUNA2000)"][3] == gen.CONTROL_MAPPED
    # Read only and untested: two of the plugins of SolaX Modbus beside SolaX's own.
    for brand in ("Sofar", "Growatt"):
        row = next(row for name, row in rows.items() if name.startswith(brand))
        assert row[2].startswith("Yes, untested: ") and row[3].startswith("Not mapped") and row[4] == "Nothing yet"
    # Solinteg: read untested, its commands mapped and never run on a device.
    row = next(row for name, row in rows.items() if name.startswith("Solinteg"))
    assert row[2].startswith("Yes, untested: ") and row[3] == gen.CONTROL_MAPPED and row[4] == "Nothing yet"
    # FoxESS: grid meter, battery power and level read, untested, and read only.
    row = next(row for name, row in rows.items() if name.startswith("FoxESS"))
    assert row[2] == "Yes, untested: grid meter, battery power, battery level" and row[3].startswith("Not mapped: read only")
    # SAJ: the Modbus integration's battery power and level are read, untested, and read only.
    row = next(row for name, row in rows.items() if name.startswith("SAJ"))
    assert row[2].startswith("Yes, untested: battery power, battery level") and row[3].startswith("Not mapped: read only")
    assert row[4] == "Nothing yet"
    assert "\n## Hybrid inverters and home batteries: overview\n" in gen.render()
